// Real network tRPC client, replaced with a direct call into the local
// backend (local-backend.ts). See that file's header comment for why: the
// real private `api` server isn't part of this open-source repo. Every
// procedure path below matches an actual `api.<...>.query/mutate(...)` or
// `apiProxy.<...>.query(...)` call site in this codebase — same shape, same
// nesting — so the rest of the app (stores, screens) needed zero changes.
import { createApiProxy } from "./create-api-proxy.ts";
import * as backend from "./local-backend.ts";

const query =
  <Args extends unknown[], R>(fn: (...args: Args) => Promise<R>) =>
  (...args: Args) =>
    fn(...args);

const mutate = query;

export const api = {
  me: {
    info: { query: query(backend.meInfo) },
    deleteAccount: { mutate: mutate(backend.deleteAccount) },
  },
  userSettings: { mutate: mutate(backend.userSettingsUpdate) },

  deck: {
    create: { mutate: mutate(backend.deckCreate) },
    update: { mutate: mutate(backend.deckUpdate) },
    deckWithCards: { query: query(backend.deckWithCards) },
    byId: { query: query(backend.deckById) },
    decksCreatedByMe: { query: query(backend.decksCreatedByMe) },
    addToMine: { mutate: mutate(async () => ({})) },
  },
  card: {
    add: { mutate: mutate(backend.cardAdd) },
    update: { mutate: mutate(backend.cardUpdate) },
    delete: { mutate: mutate(backend.cardDelete) },
    deleteMany: { mutate: mutate(backend.cardDeleteMany) },
    moveToOtherDeck: { mutate: mutate(backend.cardMoveToOtherDeck) },
    createMissingReverse: { mutate: mutate(backend.cardCreateMissingReverse) },
  },
  folder: {
    addToMine: { mutate: mutate(async () => ({})) },
    folderWithDecksCards: { query: query(backend.folderWithDecksCards) },
  },
  folderUpsert: { mutate: mutate(backend.folderUpsert) },
  libraryItem: {
    delete: { mutate: mutate(backend.libraryItemDelete) },
    deletionInfo: { query: query(backend.libraryItemDeletionInfo) },
  },

  cardsReview: { mutate: mutate(backend.cardsReview) },

  catalog: {
    list: { query: query(backend.catalogList) },
    deckCategories: { query: query(backend.catalogDeckCategories) },
  },

  currentUserStats: { query: query(backend.currentUserStats) },
  myStatisticsReviewDays: { query: query(backend.myStatisticsReviewDays) },
  myStatistics: { query: query(backend.currentUserStats) },
  weekHeatmap: { query: query(backend.weekHeatmap) },
  leaderboard: { query: query(backend.leaderboard) },

  teacherStatistics: { query: query(backend.teacherStatisticsDecks) },
  teacherStatisticsDecks: { query: query(backend.teacherStatisticsDecks) },
  teacherStatisticsStudents: { query: query(backend.teacherStatisticsStudents) },

  mcpOAuth: {
    connections: { query: query(backend.mcpConnections) },
    disconnect: { mutate: mutate(async () => ({})) },
  },
  mcpToken: { getMyToken: { query: query(backend.mcpToken) } },

  activePlan: { query: query(backend.activePlan) },
  plans: { query: query(async () => [] as unknown[]) },
  setDevPlan: { mutate: mutate(async () => ({})) },
  stripeOrderPlan: { mutate: mutate(backend.signedUrlGenerate) },
  starsOrderPlan: { mutate: mutate(backend.signedUrlGenerate) },
  cardsFreeze: { mutate: mutate(async () => ({})) },

  anki: { import: { mutate: mutate(backend.ankiImport) } },
  signedUrl: { generate: { mutate: mutate(backend.signedUrlGenerate) } },
  todos: { list: { query: query(async () => []) } },

  getByShareId: { query: query(backend.getByShareId) },

  // Auth is bypassed entirely for Soroush (see soroush-platform.ts +
  // local-backend.ts, which seed the single local user directly from
  // Soroush's initDataUnsafe.user) — these exist only so nothing crashes if
  // some code path still references them.
  telegramSignin: { mutate: mutate(async () => ({ browserToken: "" })) },
  telegramSigninConfig: { query: query(async () => ({ botUsername: "" })) },
  googleSignin: { mutate: mutate(async () => ({ browserToken: "" })) },
} as const;

export const apiProxy = createApiProxy(api);
