// Compatibility shim for the private `api` workspace package.
//
// packages/frontend imports ~50 symbols from "api" (types + pure helper
// functions + the FSRS scheduling wrapper). The REAL `api` package (a
// Cloudflare Worker with Hono + Drizzle + Postgres + Stripe + grammy, per
// pnpm-lock.yaml) was never published to this open-source copy of the repo
// and doesn't exist anywhere we have access to — confirmed by checking every
// branch of the upstream GitHub repo.
//
// This package reimplements the *shared, pure* surface the frontend actually
// needs at runtime: language/plural helpers, the FSRS review algorithm (via
// the real `ts-fsrs` library — the exact dependency the private package used,
// per pnpm-lock.yaml), and permissive types for everything else (the build
// doesn't type-check — vite/esbuild only transpiles — so a loose type here
// costs nothing at runtime; only the VALUES below need to be real).
//
// What this does NOT and CANNOT reconstruct: the actual tRPC server, the
// database schema, Stripe billing, the curated public deck catalog content,
// or any other user's data (leaderboard, teacher/student relations). Those
// need real infrastructure this repo doesn't ship with.

import {
  Card as FsrsCard,
  createEmptyCard,
  fsrs,
  generatorParameters,
  Rating,
  State,
} from "ts-fsrs";

