// ---------------------------------------------------------------------------
// Language helpers (real implementations)
// ---------------------------------------------------------------------------

export type LanguageShared = "en" | "ru" | "es" | "pt-br" | "ar" | "fa" | "uk";

export const languagesShared: LanguageShared[] = ["en", "ru", "es", "pt-br", "ar", "fa", "uk"];

export const isLanguage = (value: unknown): value is LanguageShared =>
  typeof value === "string" && (languagesShared as string[]).includes(value);

export const isRtlLanguage = (language: LanguageShared) => language === "ar" || language === "fa";

const NATIVE_NAMES: Record<LanguageShared, string> = {
  en: "English",
  ru: "Русский",
  es: "Español",
  "pt-br": "Português",
  ar: "العربية",
  fa: "فارسی",
  uk: "Українська",
};

export const languageSharedToHuman = (language: LanguageShared) => NATIVE_NAMES[language] ?? language;

export const landingLanguages: LanguageShared[] = languagesShared;

export const getUserLanguage = (user: {
  language_code?: string | null;
  forceLanguageCode?: LanguageShared | null;
}): LanguageShared => {
  if (user.forceLanguageCode && isLanguage(user.forceLanguageCode)) {
    return user.forceLanguageCode;
  }
  const code = (user.language_code || "en").toLowerCase();
  if (code.startsWith("fa")) return "fa";
  if (code.startsWith("ar")) return "ar";
  if (code.startsWith("ru")) return "ru";
  if (code.startsWith("uk")) return "uk";
  if (code.startsWith("es")) return "es";
  if (code.startsWith("pt")) return "pt-br";
  return "en";
};

// Intl.PluralRules locale needs a real BCP-47 tag; our internal `pt-br` code
// already is one, the rest map 1:1.
const PLURAL_LOCALE: Record<LanguageShared, string> = {
  en: "en",
  ru: "ru",
  es: "es",
  "pt-br": "pt-BR",
  ar: "ar",
  fa: "fa",
  uk: "uk",
};

type PluralForms = Partial<Record<"zero" | "one" | "two" | "few" | "many" | "other", string>>;

export const selectPluralForm = (language: string, count: number, forms: PluralForms): string => {
  try {
    const locale = PLURAL_LOCALE[language as LanguageShared] ?? language;
    const rule = new Intl.PluralRules(locale).select(count);
    return forms[rule] ?? forms.other ?? String(count);
  } catch {
    return forms.other ?? String(count);
  }
};

export const languageCatalogItemAvailableInToNative = (code: LanguageCatalogItemAvailableIn) =>
  isLanguage(code) ? languageSharedToHuman(code) : code;

// ---------------------------------------------------------------------------
// Generic Translator<Lang, Dict> (used directly by screens/mcp-settings)
// ---------------------------------------------------------------------------

export class Translator<Lang extends string, Dict extends Record<string, string>> {
  constructor(
    private resources: Partial<Record<Lang, Dict>>,
    private getLang: () => Lang,
  ) {}

  translate(key: keyof Dict, defaultValue?: string): string {
    const lang = this.getLang();
    const dict = this.resources[lang] ?? Object.values(this.resources)[0];
    const value = dict?.[key];
    return (value as string) ?? defaultValue ?? String(key);
  }
}

