// ---------------------------------------------------------------------------
// FSRS spaced-repetition scheduling — real implementation via ts-fsrs, the
// exact library the private `api` package also depended on.
// ---------------------------------------------------------------------------

export type FsrsState = number; // ts-fsrs `State` enum value (0=New..3=Relearning)

export type FsrsReviewState = {
  due: string; // ISO date string
  stability: number;
  difficulty: number;
  elapsedDays: number;
  scheduledDays: number;
  learningSteps: number;
  reps: number;
  lapses: number;
  fsrsState: FsrsState;
  lastReviewDate: string | null;
};

export type CardToReviewDbType = FsrsReviewState & { id: number; deckId: number };

export type ReviewOutcome = "again" | "hard" | "good" | "easy";

const scheduler = fsrs(generatorParameters({ enable_fuzz: false }));

const RATING_BY_OUTCOME: Record<ReviewOutcome, Rating> = {
  again: Rating.Again,
  hard: Rating.Hard,
  good: Rating.Good,
  easy: Rating.Easy,
};

const cardToState = (card: FsrsCard): FsrsReviewState => ({
  due: card.due.toISOString(),
  stability: card.stability,
  difficulty: card.difficulty,
  elapsedDays: card.elapsed_days,
  scheduledDays: card.scheduled_days,
  learningSteps: card.learning_steps,
  reps: card.reps,
  lapses: card.lapses,
  fsrsState: card.state as number,
  lastReviewDate: card.last_review ? card.last_review.toISOString() : null,
});

const stateToCardInput = (state: FsrsReviewState) => ({
  due: state.due,
  stability: state.stability,
  difficulty: state.difficulty,
  elapsed_days: state.elapsedDays,
  scheduled_days: state.scheduledDays,
  learning_steps: state.learningSteps,
  reps: state.reps,
  lapses: state.lapses,
  state: state.fsrsState as State,
  last_review: state.lastReviewDate ?? undefined,
});

export const createInitialFsrsReviewState = (now: Date): FsrsReviewState => cardToState(createEmptyCard(now));

export const reviewCard = <T extends FsrsReviewState>(
  now: Date,
  current: T,
  outcome: ReviewOutcome,
): FsrsReviewState => {
  const result = scheduler.next(stateToCardInput(current), now, RATING_BY_OUTCOME[outcome]);
  return cardToState(result.card);
};

export const previewReviewCard = (now: Date, current: FsrsReviewState): Record<ReviewOutcome, FsrsReviewState> => {
  const preview = scheduler.repeat(stateToCardInput(current), now);
  return {
    again: cardToState(preview[Rating.Again].card),
    hard: cardToState(preview[Rating.Hard].card),
    good: cardToState(preview[Rating.Good].card),
    easy: cardToState(preview[Rating.Easy].card),
  };
};

export const getDaysUntilDue = (due: string, now: Date = new Date()) => {
  const diffMs = new Date(due).getTime() - now.getTime();
  return Math.max(0, Math.ceil(diffMs / (24 * 60 * 60 * 1000)));
};

// Is a card "new" (never reviewed) vs a "repeat" (has been graded before)?
// Mirrors the real app's card.type: "new" | "repeat" split.
export const cardReviewType = (state: Pick<FsrsReviewState, "fsrsState">): CardReviewType =>
  state.fsrsState === State.New ? "new" : "repeat";
