// Mirrors lib/platform/telegram/telegram-web-app.ts, but for the Soroush
// Plus WebApp SDK (window.Soroush.WebApp), whose surface intentionally
// mirrors Telegram's Mini App API (see docs: "برنامک‌ها در سروش‌پلاس").

export type SoroushThemeParams = {
  bg_color?: string;
  text_color?: string;
  hint_color?: string;
  link_color?: string;
  button_color?: string;
  button_text_color?: string;
  secondary_bg_color?: string;
};

export type SoroushUser = {
  id: number;
  first_name: string;
  last_name?: string;
  username?: string;
  language_code?: string;
};

export type SoroushWebApp = {
  version?: string;
  platform?: string;
  themeParams: SoroushThemeParams;
  colorScheme: "light" | "dark";
  initData: string;
  initDataUnsafe?: { user?: SoroushUser; start_param?: string };
  ready: () => void;
  expand: () => void;
  close: () => void;
  isVersionAtLeast: (version: string) => boolean;
  onEvent: (event: string, handler: (...args: unknown[]) => void) => void;
  offEvent: (event: string, handler: (...args: unknown[]) => void) => void;
  openLink?: (url: string) => void;
  showAlert?: (message: string, callback?: () => void) => void;
  showConfirm?: (message: string, callback?: (ok: boolean) => void) => void;
  HapticFeedback?: {
    impactOccurred: (style: string) => void;
    notificationOccurred: (type: string) => void;
    selectionChanged: () => void;
  };
};

declare global {
  interface Window {
    Soroush?: { WebApp: SoroushWebApp };
  }
}

export const isRunningWithinSoroush = () => typeof window !== "undefined" && !!window.Soroush?.WebApp;

export const getSoroushWebApp = (): SoroushWebApp => {
  if (!window.Soroush?.WebApp) {
    throw new Error("Soroush WebApp SDK is not available");
  }
  return window.Soroush.WebApp;
};

// Every native SDK call is wrapped: on real devices with an older client (or
// when the SDK is simply loaded outside the Soroush app shell), calling an
// unsupported method throws `WebAppMethodUnsupported` instead of the field
// just being absent — confirmed while testing this integration.
export const safeSoroushCall = (fn: () => void) => {
  try {
    fn();
  } catch {
    // ignore: unsupported on this client version
  }
};
