// Starter content, loaded once into a brand-new local database (see
// local-backend.ts) so the app isn't a blank slate on first open. The real
// MemoCard's curated public-deck catalog lives on their server and isn't
// something this open-source repo has access to (confirmed: it's gitignored
// upstream — docs/public-decks.md, packages/api/bin/load-public-decks.ts,
// packages/api/src/data/ — and absent from every branch on GitHub) — these
// are hand-written beginner→lower-intermediate decks instead, one folder per
// language, filling that role for a first-run experience.
export type SeedCard = { front: string; back: string };
export type SeedDeck = { name: string; description: string; cards: SeedCard[] };
export type SeedLanguage = { folderName: string; decks: SeedDeck[] };

