// A local, in-browser stand-in for the private tRPC `api` server.
//
// The real backend (Cloudflare Worker + Postgres, see pnpm-lock.yaml for
// packages/api's real dependency list) isn't part of this open-source repo.
// This module implements the same procedure surface the frontend actually
// calls (found by grepping every `api.<x>.<y>.query/mutate(...)` call site),
// backed by localStorage instead of a real database — so the real screens
// (main-screen, deck-review, deck-form, card-form, folder-form,
// user-settings) can run standalone, for a single device/browser, with no
// server and no account system.
//
// Deliberately NOT implemented (return empty/stubbed data): payments, the
// curated public deck catalog, cross-user leaderboard, teacher/student
// features, MCP OAuth, and Anki import/file uploads — those need real
// infrastructure (a payment processor, other real users, proprietary
// content) that a self-hosted single-user instance can't provide.
import {
  CardReviewType,
  CardToReviewDbType,
  DeckCardDbType,
  DeckWithCardsDbType,
  FolderWithDeckIdDbType,
  FsrsReviewState,
  ReviewOutcome,
  UserDbType,
  cardReviewType,
  createInitialFsrsReviewState,
  reviewCard,
} from "api";
import { getCurrentSoroushUser } from "./current-user.ts";
import { seedLanguages } from "./seed-decks.ts";

const STORAGE_KEY = "soroush_memocard_db_v1";

type StoredCard = DeckCardDbType & { review: FsrsReviewState; createdAt: number };
type StoredDeck = Omit<DeckWithCardsDbType, "deckCards"> & {
  createdAt: number;
  cards: StoredCard[];
};

type Db = {
  nextId: number;
  user: UserDbType;
  decks: StoredDeck[];
  folders: FolderWithDeckIdDbType[];
};

const now = () => Date.now();

const createDefaultUser = (): UserDbType => {
  const soroushUser = getCurrentSoroushUser();
  return {
    id: soroushUser?.id ?? 1,
    first_name: soroushUser?.first_name ?? "کاربر",
    last_name: soroushUser?.last_name ?? null,
    username: soroushUser?.username ?? null,
    language_code: soroushUser?.language_code ?? "fa",
    isSpeakingCardEnabled: false,
  };
};

// Turns the hand-written starter content (seed-decks.ts) into real stored
// decks/cards/folders, each with fresh ids and a real initial FSRS review
// state — only used the very first time the app runs on a device (empty
// db). One folder per language, matching the real app's folder feature.
const buildSeedContent = (
  startId: number,
  authorId: number,
): { decks: StoredDeck[]; folders: FolderWithDeckIdDbType[]; nextId: number } => {
  let id = startId;
  const nowMs = now();
  const decks: StoredDeck[] = [];
  const folders: FolderWithDeckIdDbType[] = [];

  seedLanguages.forEach((language) => {
    const folderId = id++;

    language.decks.forEach((seedDeck) => {
      const cards: StoredCard[] = seedDeck.cards.map((seedCard) => ({
        id: id++,
        deckId: 0, // set below, once the deck's own id is known
        front: seedCard.front,
        back: seedCard.back,
        example: null,
        answerType: "remember",
        answers: [],
        options: null,
        createdAt: nowMs,
        review: createInitialFsrsReviewState(new Date(nowMs)),
      }));

      const deckId = id++;
      cards.forEach((card) => (card.deckId = deckId));

      decks.push({
        id: deckId,
        name: seedDeck.name,
        description: seedDeck.description,
        authorId,
        isPublic: false,
        speakField: null,
        speakLocale: null,
        createdAt: nowMs,
        cards,
      });

      folders.push({
        folder_id: folderId,
        folder_title: language.folderName,
        folder_description: null,
        folder_author_id: authorId,
        folder_share_id: "",
        folder_is_public: false,
        deck_id: deckId,
      });
    });
  });

  return { decks, folders, nextId: id };
};

let db: Db | null = null;

const load = (): Db => {
  if (db) return db;
  const raw = localStorage.getItem(STORAGE_KEY);
  if (raw) {
    try {
      db = JSON.parse(raw) as Db;
      return db;
    } catch {
      // fall through to a fresh db
    }
  }

  const user = createDefaultUser();
  const { decks, folders, nextId: nextIdAfterSeed } = buildSeedContent(1, user.id);
  db = { nextId: nextIdAfterSeed, user, decks, folders };
  save();
  return db;
};

const save = () => {
  if (!db) return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
};

const nextId = () => {
  const d = load();
  const id = d.nextId;
  d.nextId += 1;
  return id;
};

const notFound = (message: string): never => {
  const error = new Error(message) as Error & { data?: { code: string } };
  error.data = { code: "NOT_FOUND" };
  throw error;
};

const findDeck = (deckId: number): StoredDeck => {
  const deck = load().decks.find((d) => d.id === deckId);
  if (!deck) return notFound(`Deck ${deckId} not found`);
  return deck;
};

const findCard = (cardId: number): { deck: StoredDeck; card: StoredCard } => {
  for (const deck of load().decks) {
    const card = deck.cards.find((c) => c.id === cardId);
    if (card) return { deck, card };
  }
  return notFound(`Card ${cardId} not found`);
};

// --- Serialization: strip the internal `review`/`createdAt` bookkeeping
// fields from what the real DeckWithCardsDbType/DeckCardDbType shape has ---

const toPublicCard = (card: StoredCard): DeckCardDbType => {
  const { review: _review, createdAt: _createdAt, ...rest } = card;
  return rest;
};

const toPublicDeck = (deck: StoredDeck): DeckWithCardsDbType => {
  const { cards, createdAt: _createdAt, ...rest } = deck;
  return { ...rest, deckCards: cards.map(toPublicCard) };
};

const buildCardsToReview = (): CardToReviewDbType[] => {
  const nowMs = now();
  const result: CardToReviewDbType[] = [];
  for (const deck of load().decks) {
    for (const card of deck.cards) {
      if (new Date(card.review.due).getTime() <= nowMs) {
        result.push({
          id: card.id,
          deckId: deck.id,
          type: cardReviewType(card.review) as CardReviewType,
          ...card.review,
        });
      }
    }
  }
  return result;
};

const deckMutationResult = (deckId: number) => ({
  deck: toPublicDeck(findDeck(deckId)),
  folders: load().folders,
  cardsToReview: buildCardsToReview(),
});

// --- me.info -----------------------------------------------------------

export const meInfo = async () => {
  const d = load();
  return {
    user: d.user,
    plan: null as { type: "pro" | "teacher"; until_date: string | null } | null,
    myDecks: d.decks.map((deck) => ({ ...toPublicDeck(deck), isPublic: false })),
    publicDecks: [] as Array<DeckWithCardsDbType & { authorId: number; deckCategory: null }>,
    folders: d.folders,
    cardsToReview: buildCardsToReview(),
  };
};

export const deleteAccount = async () => {
  localStorage.removeItem(STORAGE_KEY);
  db = null;
};

export const userSettingsUpdate = async (input: {
  isRemindNotifyEnabled: boolean;
  isSpeakingCardEnabled: boolean;
  language: string | null;
  remindNotificationTime: string;
}) => {
  const d = load();
  d.user.isRemindEnabled = input.isRemindNotifyEnabled;
  d.user.isSpeakingCardEnabled = input.isSpeakingCardEnabled;
  d.user.lastRemindedDate = input.remindNotificationTime;
  if (input.language !== null) {
    d.user.forceLanguageCode = input.language as UserDbType["forceLanguageCode"];
  }
  save();
  return { user: d.user };
};

// --- decks ---------------------------------------------------------------

export const deckCreate = async (input: { title: string; description: string | null; folderId?: number }) => {
  const d = load();
  const deck: StoredDeck = {
    id: nextId(),
    name: input.title,
    description: input.description,
    authorId: d.user.id,
    isPublic: false,
    speakField: null,
    speakLocale: null,
    createdAt: now(),
    cards: [],
  };
  d.decks.push(deck);

  if (input.folderId !== undefined) {
    d.folders.push({
      folder_id: input.folderId,
      folder_title: "",
      folder_description: null,
      folder_author_id: d.user.id,
      folder_share_id: "",
      folder_is_public: false,
      deck_id: deck.id,
    });
  }

  save();
  return deckMutationResult(deck.id);
};

export const deckUpdate = async (input: {
  id: number;
  title: string;
  description: string | null;
  speakLocale?: string | null;
  speakField?: "front" | "back" | null;
  folderId?: number;
}) => {
  const deck = findDeck(input.id);
  deck.name = input.title;
  deck.description = input.description;
  if (input.speakLocale !== undefined) deck.speakLocale = input.speakLocale;
  if (input.speakField !== undefined) deck.speakField = input.speakField;

  if (input.folderId !== undefined) {
    const d = load();
    if (!d.folders.some((f) => f.deck_id === deck.id && f.folder_id === input.folderId)) {
      d.folders = d.folders.filter((f) => f.deck_id !== deck.id);
      d.folders.push({
        folder_id: input.folderId,
        folder_title: "",
        folder_description: null,
        folder_author_id: d.user.id,
        folder_share_id: "",
        folder_is_public: false,
        deck_id: deck.id,
      });
    }
  }

  save();
  return deckMutationResult(deck.id);
};

export const deckWithCards = async (input: { deckId: number }) => toPublicDeck(findDeck(input.deckId));

export const deckById = async (input: { deckId: number }) => toPublicDeck(findDeck(input.deckId));

export const decksCreatedByMe = async () => {
  const d = load();
  return d.decks.map((deck) => ({
    ...toPublicDeck(deck),
    folderId: d.folders.find((f) => f.deck_id === deck.id)?.folder_id,
  }));
};

export const deckDelete = async (input: { id: number }) => {
  const d = load();
  d.decks = d.decks.filter((deck) => deck.id !== input.id);
  d.folders = d.folders.filter((f) => f.deck_id !== input.id);
  save();
  return { folders: d.folders };
};

// --- folders ---------------------------------------------------------------

export const folderUpsert = async (input: {
  id?: number;
  title: string;
  description: string | null;
  deckIds: number[];
}) => {
  const d = load();
  const folderId = input.id ?? nextId();

  d.folders = d.folders.filter((f) => f.folder_id !== folderId);
  input.deckIds.forEach((deckId) => {
    d.folders.push({
      folder_id: folderId,
      folder_title: input.title,
      folder_description: input.description,
      folder_author_id: d.user.id,
      folder_share_id: "",
      folder_is_public: false,
      deck_id: deckId,
    });
  });

  save();
  return {
    folders: d.folders,
    folder: { id: folderId, name: input.title, description: input.description },
  };
};

export const folderWithDecksCards = async (input: { folderId: number }) => {
  const d = load();
  const rows = d.folders.filter((f) => f.folder_id === input.folderId);
  if (rows.length === 0) return notFound(`Folder ${input.folderId} not found`);
  const decks = rows.map((row) => toPublicDeck(findDeck(row.deck_id)));
  return {
    id: input.folderId,
    name: rows[0].folder_title,
    description: rows[0].folder_description,
    authorId: rows[0].folder_author_id,
    shareId: rows[0].folder_share_id,
    isPublic: rows[0].folder_is_public,
    decks,
  };
};

export const folderDelete = async (input: { id: number }) => {
  const d = load();
  d.folders = d.folders.filter((f) => f.folder_id !== input.id);
  save();
  return { folders: d.folders };
};

// --- cards -----------------------------------------------------------------

type CardInput = {
  front: string;
  back: string;
  example: string | null;
  answerType: "remember" | "choice_single";
  answers?: Array<{ id: string; text: string; isCorrect: boolean }>;
  options?: DeckCardDbType["options"];
};

export const cardAdd = async (input: { deckId: number; card: CardInput }) => {
  const deck = findDeck(input.deckId);
  const card: StoredCard = {
    id: nextId(),
    deckId: input.deckId,
    front: input.card.front,
    back: input.card.back,
    example: input.card.example,
    answerType: input.card.answerType,
    answers: input.card.answers ?? [],
    options: input.card.options ?? null,
    createdAt: now(),
    review: createInitialFsrsReviewState(new Date()),
  };
  deck.cards.push(card);
  save();
  return { ...deckMutationResult(deck.id), createdCards: [toPublicCard(card)] };
};

export const cardUpdate = async (input: {
  id: number;
  front: string;
  back: string;
  example: string | null;
  answerType: "remember" | "choice_single";
  answers?: Array<{ id: string; text: string; isCorrect: boolean }>;
  options?: DeckCardDbType["options"];
}) => {
  const { deck, card } = findCard(input.id);
  card.front = input.front;
  card.back = input.back;
  card.example = input.example;
  card.answerType = input.answerType;
  if (input.answers !== undefined) card.answers = input.answers;
  if (input.options !== undefined) card.options = input.options;
  save();
  return deckMutationResult(deck.id);
};

export const cardDelete = async (input: { id: number }) => {
  const { deck } = findCard(input.id);
  deck.cards = deck.cards.filter((c) => c.id !== input.id);
  save();
  return deckMutationResult(deck.id);
};

export const cardDeleteMany = async (input: { ids: number[] }) => {
  const d = load();
  let deckId: number | null = null;
  d.decks.forEach((deck) => {
    if (deck.cards.some((c) => input.ids.includes(c.id))) deckId = deck.id;
    deck.cards = deck.cards.filter((c) => !input.ids.includes(c.id));
  });
  save();
  return deckId ? deckMutationResult(deckId) : { folders: d.folders, cardsToReview: buildCardsToReview() };
};

export const cardMoveToOtherDeck = async (input: { cardIds: number[]; targetDeckId: number }) => {
  const d = load();
  const targetDeck = findDeck(input.targetDeckId);
  let sourceDeckId: number | null = null;

  d.decks.forEach((deck) => {
    const moving = deck.cards.filter((c) => input.cardIds.includes(c.id));
    if (moving.length === 0) return;
    sourceDeckId = deck.id;
    deck.cards = deck.cards.filter((c) => !input.cardIds.includes(c.id));
    moving.forEach((card) => {
      card.deckId = targetDeck.id;
      targetDeck.cards.push(card);
    });
  });

  save();
  return deckMutationResult(sourceDeckId ?? targetDeck.id);
};

export const cardCreateMissingReverse = async (input: { deckId: number }) => {
  // Not implemented for the local backend (no real "reverse card" content
  // generation) — return the deck unchanged rather than crashing the caller.
  return { ...deckMutationResult(input.deckId), createdCards: [] as DeckCardDbType[] };
};

// --- review ------------------------------------------------------------

export const cardsReview = async (input: { cards: Array<{ id: number; outcome: ReviewOutcome }> }) => {
  const reviewedAt = new Date();
  input.cards.forEach(({ id, outcome }) => {
    const { card } = findCard(id);
    card.review = reviewCard(reviewedAt, card.review, outcome);
  });
  save();
  return { cardsToReview: buildCardsToReview() };
};

