export const libraryItemDeletionInfo = async () => ({ cardsCount: 0, canDelete: true });

export const libraryItemDelete = async (input: { type: "deck" | "folder"; id: number }) => {
  if (input.type === "deck") return deckDelete({ id: input.id });
  return folderDelete({ id: input.id });
};

export const currentUserStats = async () => ({ totalReviews: 0, streakDays: 0 });
export const myStatisticsReviewDays = async () => [] as Array<{ date: string; count: number }>;

// Real shape (see screens/deck-list/week-heatmap.tsx): { currentStreak, days:
// [{date, intensity}] for the last 7 days }. We don't keep a historical
// review log (only current per-card review state), so this always reports
// an empty week rather than a real streak — a real streak needs that log.
export const weekHeatmap = async () => {
  const days = Array.from({ length: 7 }).map((_, i) => {
    const d = new Date();
    d.setDate(d.getDate() - (6 - i));
    return { date: d.toISOString().slice(0, 10), intensity: 0 };
  });
  return { currentStreak: 0, days };
};

