import { isRunningWithinSoroush, getSoroushWebApp } from "../lib/platform/soroush/soroush-web-app.ts";

// Used only to seed the local backend's single user record on first run —
// see local-backend.ts. Reads window.Soroush directly (rather than going
// through the `platform` singleton / SoroushPlatform class) to avoid a
// circular import: trpc-api.ts -> local-backend.ts -> here, and
// soroush-platform.ts -> browser-platform.ts -> trpc-api.ts already forms a
// cycle on its own.
export const getCurrentSoroushUser = () => {
  if (!isRunningWithinSoroush()) {
    return null;
  }
  return getSoroushWebApp().initDataUnsafe?.user ?? null;
};
