import { TelegramPlatform } from "./telegram/telegram-platform.ts";
import { BrowserPlatform } from "./browser/browser-platform.ts";
import { isRunningWithinTelegram } from "./is-running-within-telegram.ts";
import { isRunningWithinSoroush } from "./soroush/soroush-web-app.ts";
import { PlatformSchemaType } from "api";
import { LanguageShared } from "api";

export type HapticType =
  | "error"
  | "success"
  | "warning"
  | "light"
  | "medium"
  | "heavy"
  | "selection";

export type PlatformTheme = {
  buttonColor: string;
  hintColor: string;
  buttonTextColor: string;
};

export interface Platform {
  readonly isMobile: boolean;
  readonly isMainButtonVisible: boolean;
  initialize(): void;
  getInitData(): string | null;
  openExternalLink(link: string): void;
  openInternalLink(link: string): void;
  getTheme(): PlatformTheme;
  getClientData(): PlatformSchemaType;
  getLanguageCached(): LanguageShared;
  setLanguageCached(language: LanguageShared): void;
  getStartParam(): string | undefined;
  openInvoiceLink(link: string): void;
  haptic(type: HapticType): void;
}

export type UseMainButtonType = (
  text: string | (() => string),
  onClick: () => void,
  condition?: () => boolean,
  deps?: any[],
  options?: {
    hasShineEffect?: boolean;
    isAboveBottomSheet?: boolean;
  },
) => void;

export type UseBackButtonType = (onBack: () => void, deps?: any[]) => void;

export type ShowConfirmType = (text: string) => Promise<boolean>;

const createPlatform = (): Platform => {
  // Soroush Plus is handled as a flavor of BrowserPlatform (see the
  // isRunningWithinSoroush() branches inside that class) rather than a
  // separate subclass: mobx's makeAutoObservable (used in BrowserPlatform's
  // constructor) doesn't support subclassing, and it also locks its bound
  // methods as non-writable/non-configurable, so overriding them after
  // construction isn't possible either — both were tried and failed while
  // wiring this up.
  if (isRunningWithinSoroush()) {
    return new BrowserPlatform();
  }
  return isRunningWithinTelegram()
    ? new TelegramPlatform()
    : new BrowserPlatform();
};

export const platform = createPlatform();
